function loadManualBlocks(): Block[] {
  const dir = path.resolve(__dirname, "..", "migrations", "_manual");
  if (!fs.existsSync(dir)) return [];
  return fs.readdirSync(dir)
    .filter(f => f.endsWith(".sql"))
    .sort()
    .map(f => {
      const sql = fs.readFileSync(path.join(dir, f), "utf-8");
      return { id: "manual_" + f.replace(/\.sql$/, ""), checksum: createHash("sha256").update(sql).digest("hex"), sql };
    });
}

async function migrate() {
  const dbPath = process.env.SQLITE_PATH || path.resolve(process.cwd(), "inventory_platform.db");
  const db = new Database(dbPath);
  db.pragma("foreign_keys = ON");

  db.exec(`CREATE TABLE IF NOT EXISTS schema_migrations (
    id TEXT PRIMARY KEY,
    checksum TEXT NOT NULL,
    applied_at TEXT NOT NULL DEFAULT (datetime('now')),
    duration_ms INTEGER NOT NULL DEFAULT 0
  );`);

  const all = [...GENERATED_BLOCKS, ...loadManualBlocks()];
  const existing = db.prepare("SELECT id, checksum FROM schema_migrations").all() as Array<{ id: string; checksum: string }>;
  const seen = new Map(existing.map(r => [r.id, r.checksum]));

  let applied = 0, skipped = 0;
  for (const block of all) {
    const prior = seen.get(block.id);
    if (prior === block.checksum) { skipped++; continue; }
    if (prior && prior !== block.checksum) {
      throw new Error(`Migration ${block.id} was previously applied with a different checksum.`);
    }
    const start = Date.now();
    db.exec("BEGIN");
    try {
      db.exec(block.sql);
      db.prepare("INSERT INTO schema_migrations (id, checksum, duration_ms) VALUES (?, ?, ?)")
        .run(block.id, block.checksum, Date.now() - start);
      db.exec("COMMIT");
      console.log(`  applied ${block.id} (${Date.now() - start}ms)`);
      applied++;
    } catch (e) {
      try { db.exec("ROLLBACK"); } catch {}
      throw e;
    }
  }
  console.log(`Migrations complete: ${applied} applied, ${skipped} already up to date.`);
  db.close();
}

migrate().catch(e => { console.error(e); process.exit(1); });